
-- Tabela: chamados (Banco: portal_ouvidoria)
USE `portal_ouvidoria`;
CREATE TABLE `chamados` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `protocolo` varchar(20) NOT NULL,
  `senha_acesso` varchar(100) NOT NULL,
  `admin_responsavel_id` int(11) DEFAULT NULL,
  `transferido_por` int(11) DEFAULT NULL,
  `data_transferencia` datetime DEFAULT NULL,
  `nome_completo` varchar(150) NOT NULL,
  `email` varchar(100) NOT NULL,
  `estado` char(3) NOT NULL,
  `cidade` varchar(100) NOT NULL,
  `telefone` varchar(20) NOT NULL,
  `unidade_campus` varchar(100) NOT NULL,
  `perfil` enum('ex-aluno','colaborador','professor','outros','N/A') NOT NULL,
  `perfil_outros` varchar(100) DEFAULT NULL,
  `cpf` varchar(14) DEFAULT NULL,
  `manifestacao` enum('sugestão','reclamação','elogio','denúncia','crítica','consulta','Solicitação') NOT NULL,
  `categoria` enum('Solicitações - Ambiente Virtual de Aprendizagem (AVA)','Solicitações - TOTVS','Solicitações Pedagógicas') DEFAULT NULL,
  `subcategoria` enum('Acesso ao AVA - Login e Senha','Alteração de senha','Inclusão e exclusão de disciplinas','Visualização de notas','Inscrição na sala de Ambientação','Acesso ao TOTVS - Login e Senha','Lançamento, correção de notas','Rematrícula','Análise de Grade','Falar com o Professor da Disciplina','Falar com o Tutor da Disciplina','Falar com o Gestor do NEaD','Acessar a Biblioteca Digital','Acessar meu Office 365') DEFAULT NULL,
  `descricao` text NOT NULL,
  `anexo` varchar(255) DEFAULT NULL,
  `status` enum('em análise','respondido','finalizado','respondido drummond') DEFAULT 'em análise',
  `resposta` text DEFAULT NULL,
  `data_abertura` datetime DEFAULT current_timestamp(),
  `data_resposta` datetime DEFAULT NULL,
  `nivel_ensino` enum('colegio','faculdade','','') NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `protocolo` (`protocolo`),
  KEY `idx_chamados_admin_responsavel` (`admin_responsavel_id`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



